import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:langread/data/bundle_reader.dart';
import 'package:langread/data/import_service.dart';
import 'package:langread/state/review_session.dart';

import 'test_db.dart';

/// The critical cross-app test (plan §8): imports the bundle generated by
/// the REAL desktop `SyncService` (tool/make_fixture.py) into the Android
/// data layer. If either side changes the format, this fails.
void main() {
  final fixture =
      File('${Directory.current.path}/test/fixtures/sync-v1.zip');

  test('imports the real desktop bundle', () async {
    // Sanity: the fixture must verify with our §3.4 reader first.
    final reader = BundleReader.load(fixture.path, expectedType: 'content');
    expect(reader.manifest['counts']['topics'], 2);
    expect(reader.manifest['counts']['lessons'], 3);
    expect(reader.manifest['counts']['audio_files'], 2);

    final dir = tempDir();
    final db = testFileDb(dir);
    addTearDown(db.close);

    final stats = await ImportService(db, dir).importBundle(fixture.path);
    expect(stats.topics, 2);
    expect(stats.lessons, 3);
    expect(stats.sentences, 5);
    expect(stats.words, 8);
    expect(stats.audioFiles, 2);

    // Draft lesson is imported but not reviewable.
    final topics = await db.watchTopics().first;
    final cooking =
        topics.firstWhere((t) => t.name == 'Cooking');
    final lessons = await db.lessonsForTopic(cooking.id);
    expect(lessons.where((l) => l.status == 'complete'), hasLength(2));
    final travel = topics.firstWhere((t) => t.name == 'Travel');
    final travelLessons = await db.lessonsForTopic(travel.id);
    expect(travelLessons.where((l) => l.status == 'draft'), hasLength(1));

    // Audio files landed.
    for (final l in lessons) {
      if (l.audioPath != null) {
        expect(File('${dir.path}/audio/${l.audioPath}').existsSync(), isTrue,
            reason: 'audio for lesson ${l.id}');
      }
    }

    // A review session loads from real data and can complete.
    final first = lessons.firstWhere((l) => l.status == 'complete');
    final session = ReviewSession(db, first);
    await session.load();
    expect(session.sentences, isNotEmpty);
    expect(session.newWordTexts, contains('锅'));
    expect(session.reviewWords.map((w) => w.word), containsAll(['饭', '菜']));
    // New words are underlined, first occurrence highlighted (§6.2).
    expect(session.lookup('锅')!.listState, 'new');

    // Desktop events from the bundle are available for pending pruning.
    expect(reader.has('events.jsonl'), isTrue);
    expect(reader.readJsonLines('events.jsonl'), hasLength(2));
  });
}
